// runs on every incoming ping (2M/sec)
function onPing(userId, lat, lng) {
  store.set(userId, {lat, lng}, ttlSec=30);
  const friends = socialGraph.getFriends(userId);   // graph lookup
  for (const f of friends) {
    const loc = store.get(f);                        // geo lookup per friend
    if (loc && haversine(lat, lng, loc.lat, loc.lng) <= 5000)
      push(f, {userId, lat, lng});                   // direct push
  }
}

