// a ping for some publisher arrived on a region channel this edge subscribes to
function onRegionPing(ping) {
  for (const watcher of localWatchers) {
    const allowed = friendCache.get(watcher.id); // cached friend-id list
    if (allowed.includes(ping.userId)) {
      const d = haversine(watcher.lat, watcher.lng, ping.lat, ping.lng);
      watcher.send({ userId: ping.userId, lat: ping.lat, lng: ping.lng });
    }
  }
}
